import { createClient } from "npm:@supabase/supabase-js@2";

// ===== _shared/normalize.ts =====
/**
 * Market data normalization for poe.ninja "exchange overview" responses.
 *
 * Endpoint: GET /poe1/api/economy/exchange/current/overview?league={league}&type={type}
 *
 * Field meanings (verified against live data on 2026-11-04):
 *  - core.primary            reference currency of every primaryValue (expected: "chaos")
 *  - core.rates[id]          how many units of `id` ONE primary unit buys.
 *                            rates.divine = 0.002489  =>  1 chaos = 0.002489 divine
 *                            => divine price in chaos = 1 / rates.divine (≈ 401.8).
 *                            Reading this as "divine price" is the classic inversion bug.
 *  - line.primaryValue       price of ONE unit of the item, in primary currency (chaos).
 *  - line.volumePrimaryValue traded value expressed in chaos (NOT a unit count).
 *                            The time window is not documented by poe.ninja.
 *  - line.maxVolumeRate      units of THIS item per ONE unit of maxVolumeCurrency
 *                            (24.73 annul per 1 divine). Never use it as a price.
 *  - line.sparkline.data     cumulative % change over ~7 points (not prices!) of the item's
 *                            price measured in ITS maxVolumeCurrency (the docs: "price-trend
 *                            samples for the highest-volume pair"). So annul (pair: divine)
 *                            reports its change vs Divine, alt (pair: chaos) vs Chaos.
 *                            Verified 2026-11-04: divine (pair chaos) +17.25% matches the
 *                            classic stash endpoint's divine paySparkLine +17.10%, and chaos
 *                            (pair divine) -14.71% compounds with it to ~0% chaos-in-chaos.
 *                            The v1.0.0 prototype inverted these, flipping every trend sign.
 *
 * Rules enforced here (from the project brief):
 *  - Missing / invalid prices become null, never 0.
 *  - Missing volume becomes null, never 0.
 *  - The Divine/Chaos ratio is validated before anything else is trusted.
 */

export type Confidence = "high" | "medium" | "low";

export interface RawExchangeLine {
  id: string;
  primaryValue?: number | null;
  volumePrimaryValue?: number | null;
  maxVolumeCurrency?: string | null;
  maxVolumeRate?: number | null;
  sparkline?: { totalChange?: number | null; data?: (number | null)[] } | null;
}

export interface RawExchangeOverview {
  core: {
    primary: string;
    secondary?: string;
    rates: Record<string, number>;
    items?: { id: string; name: string; category?: string }[];
  };
  lines: RawExchangeLine[];
  items?: { id: string; name: string; category?: string; detailsId?: string }[];
}

export interface NormalizedItem {
  id: string;
  name: string;
  category: string | null;
  /** Price of one unit in Chaos Orbs. null = unknown (never 0 as a stand-in). */
  chaosValue: number | null;
  /** Price of one unit in Divine Orbs. null when chaosValue is null. */
  divineValue: number | null;
  /** Traded value in Chaos (window not documented by the source). null = unavailable. */
  volumeChaos: number | null;
  /** Approximate number of units behind the volume figure. */
  approxUnitsTraded: number | null;
  /** Currency the source measured the trend against (the highest-volume pair). */
  trendPair: string | null;
  /** 7-day % change in Chaos terms (converted from the pair when needed). */
  change7dPctChaos: number | null;
  /**
   * 7-day % change in Divine terms (removes Chaos inflation).
   * null when it cannot be derived safely.
   */
  change7dPctDivine: number | null;
  confidence: Confidence;
  /** Plain-language reasons why confidence is not "high", or why data is missing. */
  notes: string[];
}

export interface NormalizedSnapshot {
  league: string;
  category: string;
  fetchedAt: string;
  divinePriceChaos: number;
  /** % change of Divine measured in Chaos over the sparkline window. */
  divineChange7dPct: number | null;
  items: NormalizedItem[];
  warnings: string[];
}

export class DataIntegrityError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DataIntegrityError";
  }
}

/** Plausible range for 1 Divine in Chaos. Outside it we refuse the whole snapshot. */
export const DIVINE_SANITY_RANGE = { min: 20, max: 5000 } as const;
/** Two independent Divine readings must agree within this fraction. */
const DIVINE_AGREEMENT_TOLERANCE = 0.03;
/** maxVolumeRate cross-check tolerance before we attach a warning. */
const CROSS_CHECK_TOLERANCE = 0.15;

const isPositiveNumber = (v: unknown): v is number =>
  typeof v === "number" && Number.isFinite(v) && v > 0;
const isNonNegativeNumber = (v: unknown): v is number =>
  typeof v === "number" && Number.isFinite(v) && v >= 0;
const isFiniteNumber = (v: unknown): v is number =>
  typeof v === "number" && Number.isFinite(v);

/**
 * Determine the Divine price in Chaos from two independent fields and make sure
 * they agree and are plausible. Throws DataIntegrityError otherwise.
 */
export function resolveDivinePrice(raw: RawExchangeOverview): number {
  if (raw?.core?.primary !== "chaos") {
    throw new DataIntegrityError(
      `Expected primary currency "chaos", got "${raw?.core?.primary}". Refusing to guess a conversion.`,
    );
  }
  const rate = raw.core.rates?.divine;
  const fromRate = isPositiveNumber(rate) ? 1 / rate : null;
  const divineLine = raw.lines?.find((l) => l.id === "divine");
  const fromLine = isPositiveNumber(divineLine?.primaryValue) ? divineLine!.primaryValue! : null;

  const candidate = fromLine ?? fromRate;
  if (candidate === null) {
    throw new DataIntegrityError("No usable Divine price in response (neither rates.divine nor a divine line).");
  }
  if (fromLine !== null && fromRate !== null) {
    const diff = Math.abs(fromLine - fromRate) / fromLine;
    if (diff > DIVINE_AGREEMENT_TOLERANCE) {
      throw new DataIntegrityError(
        `Divine price readings disagree: line=${fromLine}, 1/rate=${fromRate.toFixed(2)} (${(diff * 100).toFixed(1)}%).`,
      );
    }
  }
  if (candidate < DIVINE_SANITY_RANGE.min || candidate > DIVINE_SANITY_RANGE.max) {
    throw new DataIntegrityError(
      `Divine price ${candidate} chaos is outside the plausible range ` +
        `${DIVINE_SANITY_RANGE.min}–${DIVINE_SANITY_RANGE.max}. Possible inversion; snapshot rejected.`,
    );
  }
  return candidate;
}

/**
 * Initial heuristic. Thin markets produce fake "+100%" signals, so the scanner
 * must be able to hide or label them.
 */
export function classifyConfidence(
  chaosValue: number | null,
  volumeChaos: number | null,
): { confidence: Confidence; approxUnits: number | null; notes: string[] } {
  if (chaosValue === null) return { confidence: "low", approxUnits: null, notes: ["No price data."] };
  if (volumeChaos === null) return { confidence: "low", approxUnits: null, notes: ["No volume data."] };
  const units = volumeChaos / chaosValue;
  // Expensive items (Mirror) trade in few units, so "few units" alone is not thin:
  // low = about one unit changed hands, or the whole market is worth < 100 chaos.
  if (units < 2 || volumeChaos < 100) {
    return {
      confidence: "low",
      approxUnits: units,
      notes: [`Very few trades (~${formatUnits(units)} units, ${Math.round(volumeChaos)} chaos). Price can move easily.`],
    };
  }
  if (units < 20 || volumeChaos < 2000) {
    return { confidence: "medium", approxUnits: units, notes: ["Moderate trading volume."] };
  }
  return { confidence: "high", approxUnits: units, notes: [] };
}

function formatUnits(u: number): string {
  return u < 10 ? u.toFixed(1) : String(Math.round(u));
}

/**
 * Convert a Chaos-terms % change into Divine terms.
 * (1 + item%) / (1 + divine%) − 1, where divine% is Divine's change in Chaos.
 */
export function toDivineTermsChange(itemPctChaos: number | null, divinePctChaos: number | null): number | null {
  if (!isFiniteNumber(itemPctChaos) || !isFiniteNumber(divinePctChaos)) return null;
  const denom = 1 + divinePctChaos / 100;
  if (denom <= 0) return null;
  return ((1 + itemPctChaos / 100) / denom - 1) * 100;
}

/** Compound two % changes: (1 + a)(1 + b) − 1. */
export function compoundChange(a: number | null, b: number | null): number | null {
  if (!isFiniteNumber(a) || !isFiniteNumber(b)) return null;
  return ((1 + a / 100) * (1 + b / 100) - 1) * 100;
}

/**
 * Express a pair-relative trend in Chaos and Divine terms.
 * divineVsChaos = Divine's own change measured in Chaos.
 */
export function trendInBothUnits(
  pairChange: number | null,
  pair: string | null | undefined,
  divineVsChaos: number | null,
): { chaos: number | null; divine: number | null } {
  if (!isFiniteNumber(pairChange)) return { chaos: null, divine: null };
  if (pair === "chaos") return { chaos: pairChange, divine: toDivineTermsChange(pairChange, divineVsChaos) };
  if (pair === "divine") return { chaos: compoundChange(pairChange, divineVsChaos), divine: pairChange };
  // Other pairs (rare) would need that pair's own trend; refuse to guess.
  return { chaos: null, divine: null };
}

/** Implied chaos price from maxVolumeRate, for cross-checking only. */
export function impliedPriceFromMaxVolume(line: RawExchangeLine, divinePriceChaos: number): number | null {
  if (!isPositiveNumber(line.maxVolumeRate)) return null;
  if (line.maxVolumeCurrency === "chaos") return 1 / line.maxVolumeRate;
  if (line.maxVolumeCurrency === "divine") return divinePriceChaos / line.maxVolumeRate;
  return null;
}

/**
 * Divine reference taken from the same league's Currency overview. Other
 * categories (Scarab, Essence, …) carry only core.rates.divine and no divine
 * line, so they borrow Divine's 7-day trend from here.
 */
export interface DivineContext {
  divinePriceChaos: number;
  divineChange7dPct: number | null;
}

/** Categories are fetched minutes apart and Divine moves fast late in a league. */
const CONTEXT_WARN_TOLERANCE = 0.1;
const CONTEXT_REJECT_TOLERANCE = 0.25;

export function normalizeExchangeOverview(
  raw: RawExchangeOverview,
  meta: { league: string; category: string; fetchedAt?: string; context?: DivineContext },
): NormalizedSnapshot {
  const divinePriceChaos = resolveDivinePrice(raw);
  const warnings: string[] = [];

  if (meta.context) {
    const ref = meta.context.divinePriceChaos;
    const diff = Math.abs(divinePriceChaos - ref) / ref;
    if (diff > CONTEXT_REJECT_TOLERANCE) {
      throw new DataIntegrityError(
        `${meta.category}: Divine ${divinePriceChaos.toFixed(1)}c differs from Currency's ${ref.toFixed(1)}c by ${(diff * 100).toFixed(0)}%.`,
      );
    }
    if (diff > CONTEXT_WARN_TOLERANCE) {
      warnings.push(`Divine ${divinePriceChaos.toFixed(1)}c vs Currency ${ref.toFixed(1)}c (${(diff * 100).toFixed(0)}% apart).`);
    }
  }

  const names = new Map<string, { name: string; category: string | null }>();
  for (const it of [...(raw.core.items ?? []), ...(raw.items ?? [])]) {
    names.set(it.id, { name: it.name, category: it.category ?? null });
  }

  // Divine's trend is only usable as the Chaos<->Divine bridge when it was
  // measured against Chaos.
  const divineLine = raw.lines.find((l) => l.id === "divine");
  const ownDivineChange =
    divineLine?.maxVolumeCurrency === "chaos" && isFiniteNumber(divineLine?.sparkline?.totalChange)
      ? divineLine!.sparkline!.totalChange!
      : null;
  const divineChange7dPct = ownDivineChange ?? meta.context?.divineChange7dPct ?? null;
  if (divineChange7dPct === null) warnings.push("Divine trend vs Chaos unavailable; 7-day changes left empty.");

  const seen = new Set<string>();
  const items: NormalizedItem[] = [];
  for (const line of raw.lines ?? []) {
    if (!line?.id) {
      warnings.push("Skipped a line without id.");
      continue;
    }
    if (seen.has(line.id)) {
      warnings.push(`Duplicate line "${line.id}" ignored.`);
      continue;
    }
    seen.add(line.id);

    const notes: string[] = [];
    const chaosValue = isPositiveNumber(line.primaryValue) ? line.primaryValue : null;
    if (chaosValue === null) notes.push("Source gave no valid price.");
    const volumeChaos = isNonNegativeNumber(line.volumePrimaryValue) ? line.volumePrimaryValue : null;

    if (chaosValue !== null) {
      const implied = impliedPriceFromMaxVolume(line, divinePriceChaos);
      if (implied !== null && Math.abs(implied - chaosValue) / chaosValue > CROSS_CHECK_TOLERANCE) {
        warnings.push(
          `"${line.id}": primaryValue ${chaosValue} vs implied ${implied.toFixed(4)} from maxVolumeRate differ by >${CROSS_CHECK_TOLERANCE * 100}%.`,
        );
        notes.push("Price sources disagree.");
      }
    }

    const pairChange = isFiniteNumber(line.sparkline?.totalChange) ? line.sparkline!.totalChange! : null;
    const trend =
      line.id === "chaos"
        ? { chaos: 0, divine: pairChange } // chaos never moves in chaos terms
        : line.id === "divine"
          ? { chaos: divineChange7dPct, divine: 0 }
          : trendInBothUnits(pairChange, line.maxVolumeCurrency, divineChange7dPct);
    const conf = classifyConfidence(chaosValue, volumeChaos);
    const info = names.get(line.id);

    items.push({
      id: line.id,
      name: info?.name ?? line.id,
      category: info?.category ?? null,
      chaosValue,
      divineValue: chaosValue === null ? null : chaosValue / divinePriceChaos,
      volumeChaos,
      approxUnitsTraded: conf.approxUnits,
      trendPair: line.maxVolumeCurrency ?? null,
      change7dPctChaos: trend.chaos,
      change7dPctDivine: trend.divine,
      confidence: conf.confidence,
      notes: [...notes, ...conf.notes],
    });
  }

  return {
    league: meta.league,
    category: meta.category,
    fetchedAt: meta.fetchedAt ?? new Date().toISOString(),
    divinePriceChaos,
    divineChange7dPct,
    items,
    warnings,
  };
}

/**
 * Display rule from the brief: total >= 1 Divine -> show Divine, else Chaos.
 * null -> "—" (never "0").
 */
export function formatValue(chaos: number | null, divinePriceChaos: number): { main: string; alt: string | null } {
  if (chaos === null || !Number.isFinite(chaos)) return { main: "—", alt: null };
  const div = chaos / divinePriceChaos;
  const fmt = (n: number) =>
    n >= 100 ? Math.round(n).toLocaleString("en-US") : n >= 10 ? n.toFixed(1) : n >= 1 ? n.toFixed(2) : n.toFixed(3);
  if (div >= 1) return { main: `${fmt(div)} div`, alt: `${fmt(chaos)} c` };
  return { main: `${fmt(chaos)} c`, alt: `${fmt(div)} div` };
}


// ===== _shared/alerts.ts =====
/**
 * Alert delivery: turns fired alert events into Discord webhook messages.
 * Pure formatting + an injected fetch, so it is tested without network.
 * All text here is user-facing and therefore English.
 */

export interface AlertEvent {
  id: number;
  alert_id: number;
  item_id: number;
  item_name: string | null;
  alert_label: string | null;
  league_id: string;
  fired_at: string;
  kind: "above" | "below" | "rise" | "drop";
  threshold: number;
  unit: "chaos" | "divine" | null;
  window_minutes: number | null;
  now_chaos: number | null;
  now_divine: number | null;
  change_pct: number | null;
  volume_chaos: number | null;
  confidence: number | null;
}

export interface DiscordEmbed {
  title: string;
  description: string;
  color: number;
  timestamp: string;
  footer: { text: string };
}
export interface DiscordPayload {
  username: string;
  content?: string;
  embeds?: DiscordEmbed[];
  allowed_mentions: { parse: string[] };
}

const GREEN = 0x2f9e44;
const RED = 0xc92a2a;
const FOOTER = "PoE Economy Tools · prices via poe.ninja · not affiliated with Grinding Gear Games";
const CONFIDENCE = ["low", "medium", "high"];
/** Discord allows at most 10 embeds per message. */
const EMBEDS_PER_MESSAGE = 10;

export const DISCORD_WEBHOOK_RE = /^https:\/\/(?:discord|discordapp)\.com\/api\/webhooks\/\d+\/[\w-]+$/;

export function windowLabel(minutes: number | null): string {
  if (!minutes) return "";
  if (minutes < 60) return `${minutes}m`;
  if (minutes % 60 === 0 && minutes < 1440) return `${minutes / 60}h`;
  if (minutes === 1440) return "24h";
  return `${minutes}m`;
}

function compactChaos(v: number): string {
  if (v >= 1_000_000) return `${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 10_000) return `${Math.round(v / 1000)}k`;
  if (v >= 1000) return `${(v / 1000).toFixed(1)}k`;
  return String(Math.round(v));
}

function signed(pct: number): string {
  const s = pct.toFixed(1);
  return pct > 0 ? `+${s}%` : pct < 0 ? `−${s.replace("-", "")}%` : "0.0%";
}

export function formatEvent(e: AlertEvent): DiscordEmbed {
  const name = e.item_name ?? `Item #${e.item_id}`;
  const up = e.kind === "rise" || e.kind === "above";
  let title: string;
  if (e.kind === "rise" || e.kind === "drop") {
    const pct = e.change_pct === null ? "?" : signed(e.change_pct);
    title = `${up ? "📈" : "📉"} ${name} ${pct} in ${windowLabel(e.window_minutes)}`;
  } else {
    const lvl = `${e.threshold} ${e.unit === "divine" ? "div" : "c"}`;
    title = `🔔 ${name} ${e.kind === "above" ? "rose above" : "fell below"} ${lvl}`;
  }

  const divinePrice = e.now_chaos && e.now_divine ? e.now_chaos / e.now_divine : null;
  const price = divinePrice ? formatValue(e.now_chaos, divinePrice) : { main: "—", alt: null };
  const lines = [
    `**Now:** ${price.main}${price.alt ? ` (${price.alt})` : ""}`,
    `**League:** ${e.league_id}`,
    `**Traded:** ${e.volume_chaos === null ? "—" : `${compactChaos(e.volume_chaos)} c`} · **Confidence:** ${
      e.confidence === null ? "—" : CONFIDENCE[e.confidence]
    }`,
  ];
  if (e.alert_label) lines.push(`**Rule:** ${e.alert_label}`);
  lines.push("_Check the live rate in game before you trade._");

  return { title, description: lines.join("\n"), color: up ? GREEN : RED, timestamp: e.fired_at, footer: { text: FOOTER } };
}

export function buildPayloads(events: AlertEvent[]): { payload: DiscordPayload; ids: number[] }[] {
  const out: { payload: DiscordPayload; ids: number[] }[] = [];
  for (let i = 0; i < events.length; i += EMBEDS_PER_MESSAGE) {
    const chunk = events.slice(i, i + EMBEDS_PER_MESSAGE);
    out.push({
      payload: { username: "PoE Economy Tools", embeds: chunk.map(formatEvent), allowed_mentions: { parse: [] } },
      ids: chunk.map((e) => e.id),
    });
  }
  return out;
}

export function testPayload(at: string): DiscordPayload {
  return {
    username: "PoE Economy Tools",
    embeds: [{
      title: "✅ Alerts are connected",
      description: "This channel will receive price alerts from PoE Economy Tools.",
      color: GREEN,
      timestamp: at,
      footer: { text: FOOTER },
    }],
    allowed_mentions: { parse: [] },
  };
}

export type PostJson = (url: string, body: unknown) => Promise<{ status: number; retryAfterMs: number | null }>;

/**
 * Sends one payload; on HTTP 429 waits the time Discord asks for (max 5 s) and
 * tries once more. Returns null on success, or an error text.
 */
export async function sendDiscord(
  post: PostJson,
  sleep: (ms: number) => Promise<void>,
  webhookUrl: string,
  payload: DiscordPayload,
): Promise<string | null> {
  if (!DISCORD_WEBHOOK_RE.test(webhookUrl)) return "Discord webhook URL is not valid";
  for (let attempt = 0; attempt < 2; attempt++) {
    let res: { status: number; retryAfterMs: number | null };
    try {
      res = await post(webhookUrl, payload);
    } catch (e) {
      return `Discord unreachable: ${e instanceof Error ? e.message : String(e)}`;
    }
    if (res.status >= 200 && res.status < 300) return null;
    if (res.status === 429 && attempt === 0) {
      await sleep(Math.min(res.retryAfterMs ?? 1000, 5000));
      continue;
    }
    if (res.status === 404 || res.status === 401) return `Discord rejected the webhook (HTTP ${res.status}); it may have been deleted`;
    return `Discord HTTP ${res.status}`;
  }
  return "Discord rate limit";
}


// ===== _shared/collector.ts =====
/**
 * Collector core: fetch poe.ninja exchange overviews for the tracked leagues,
 * normalize them, hand them to a store. No I/O of its own — fetch, storage and
 * the clock are injected so this runs the same in tests and in the Edge Function.
 *
 * poe.ninja rules followed here (https://poe.ninja/docs/api):
 *  - one backend fetches for everyone; never per-user traffic
 *  - conditional requests (ETag / If-None-Match), no cache-busting
 *  - descriptive User-Agent with a contact
 *  - modest volume: sequential requests, a pause between them, and a
 *    per-(league, category) minimum interval so repeated triggers are no-ops
 */


export const NINJA_BASE = "https://poe.ninja/poe1/api/economy";

/** PoE 1 exchange categories per https://poe.ninja/docs/api (2026-11-04). Currency must stay first. */
export const EXCHANGE_CATEGORIES = [
  "Currency",
  "Fragment",
  "Scarab",
  "Essence",
  "Fossil",
  "Resonator",
  "Oil",
  "DeliriumOrb",
  "DivinationCard",
  "Omen",
  "Tattoo",
  "Runegraft",
  "Astrolabe",
  "Artifact",
  "EnshroudingCrystal",
  "DjinnCoin",
  "Ducat",
  "AllflameEmber",
] as const;

export type LeagueKind = "challenge" | "challenge_hc" | "standard" | "hardcore";
export interface League {
  id: string;
  name: string;
  kind: LeagueKind;
}

/** fast = current challenge softcore (default view); slow = the other three. */
export type Tier = "fast" | "slow";
export const TIER_KINDS: Record<Tier, LeagueKind[]> = {
  fast: ["challenge"],
  slow: ["challenge_hc", "standard", "hardcore"],
};
/** A (league, category) is skipped if it was attempted more recently than this. */
// fast runs every 15 min (poe.ninja refreshes PoE1 about every 15 min); slow runs hourly.
export const MIN_INTERVAL_MS: Record<Tier, number> = { fast: 12 * 60_000, slow: 50 * 60_000 };

export interface FetchResult {
  status: number;
  etag: string | null;
  body: unknown;
}

export interface CategoryState {
  etag: string | null;
  lastAttemptAt: string | null;
  lastSuccessAt: string | null;
  divineChaos: number | null;
  divineChange7d: number | null;
}

export type RunStatus = "ok" | "not_modified" | "empty" | "error" | "rejected";

export interface Store {
  upsertLeagues(leagues: League[], seenAt: string): Promise<void>;
  getState(leagueId: string, category: string): Promise<CategoryState | null>;
  setState(leagueId: string, category: string, state: CategoryState): Promise<void>;
  ingest(leagueId: string, category: string, capturedAt: string, items: IngestItem[]): Promise<number>;
  recordRun(run: {
    leagueId: string;
    category: string;
    startedAt: string;
    status: RunStatus;
    divineChaos: number | null;
    itemCount: number | null;
    warnings: string[];
    error: string | null;
  }): Promise<void>;
}

export interface IngestItem {
  ninja_id: string;
  name: string;
  icon_url: string | null;
  chaos_value: number | null;
  divine_value: number | null;
  volume_chaos: number | null;
  change7d_chaos: number | null;
  change7d_divine: number | null;
  confidence: 0 | 1 | 2;
  trend_pair: string | null;
}

/** Optional alert hooks: evaluated after each stored snapshot, delivered once per run. */
export interface AlertHooks {
  evaluate(leagueId: string, category: string, at: string): Promise<AlertEvent[]>;
  deliver(events: AlertEvent[]): Promise<void>;
}

export interface CollectorDeps {
  fetchJson(url: string, etag: string | null): Promise<FetchResult>;
  store: Store;
  now(): Date;
  sleep(ms: number): Promise<void>;
  alerts?: AlertHooks;
}

export interface CollectOptions {
  tier: Tier;
  categories?: readonly string[];
  /** Stop starting new requests after this long; the next run picks up the rest. */
  budgetMs?: number;
  /** Pause between upstream requests. */
  gapMs?: number;
}

export interface CollectSummary {
  tier: Tier;
  leagues: string[];
  results: { leagueId: string; category: string; status: RunStatus | "skipped"; items?: number; note?: string }[];
  stoppedEarly: boolean;
  alerts: { fired: number; errors: string[] };
}

/**
 * Map poe.ninja's league list to our league kinds. The first entry is the current
 * challenge league; its hardcore twin is "Hardcore <name>". Anything else (events,
 * private leagues) is ignored.
 */
export function classifyLeagues(list: unknown): League[] {
  if (!Array.isArray(list) || list.length === 0) return [];
  const entries = list
    .filter((l): l is { id: string; name?: string } => !!l && typeof (l as { id?: unknown }).id === "string")
    .map((l) => ({ id: l.id, name: typeof l.name === "string" ? l.name : l.id }));
  if (entries.length === 0) return [];
  const out: League[] = [];
  const first = entries[0];
  const isPermanent = (id: string) => id === "Standard" || id === "Hardcore";
  if (!isPermanent(first.id)) out.push({ ...first, kind: "challenge" });
  for (const e of entries) {
    if (e.id === "Standard") out.push({ ...e, kind: "standard" });
    else if (e.id === "Hardcore") out.push({ ...e, kind: "hardcore" });
    else if (!isPermanent(first.id) && e.id === `Hardcore ${first.id}`) out.push({ ...e, kind: "challenge_hc" });
  }
  return out;
}

const CONFIDENCE_CODE = { low: 0, medium: 1, high: 2 } as const;

export function toIngestItems(items: NormalizedItem[], icons: Map<string, string | null>): IngestItem[] {
  return items.map((i) => ({
    ninja_id: i.id,
    name: i.name,
    icon_url: icons.get(i.id) ?? null,
    chaos_value: i.chaosValue,
    divine_value: i.divineValue,
    volume_chaos: i.volumeChaos,
    change7d_chaos: i.change7dPctChaos,
    change7d_divine: i.change7dPctDivine,
    confidence: CONFIDENCE_CODE[i.confidence],
    trend_pair: i.trendPair,
  }));
}

/** poe.ninja serves item images as relative paths under /gen/image/… */
export function iconMap(raw: RawExchangeOverview & { items?: { id: string; image?: string }[] }): Map<string, string | null> {
  const m = new Map<string, string | null>();
  for (const it of raw.items ?? []) {
    const img = (it as { image?: string }).image;
    m.set(it.id, typeof img === "string" && img.startsWith("/") ? `https://poe.ninja${img}` : null);
  }
  return m;
}

export async function collect(deps: CollectorDeps, opts: CollectOptions): Promise<CollectSummary> {
  const summary: CollectSummary = {
    tier: opts.tier, leagues: [], results: [], stoppedEarly: false, alerts: { fired: 0, errors: [] },
  };
  const fired: AlertEvent[] = [];
  try {
    await collectPrices(deps, opts, summary, fired);
  } finally {
    // Whatever happened to the prices, deliver what already fired.
    if (fired.length && deps.alerts) {
      try {
        await deps.alerts.deliver(fired);
      } catch (e) {
        summary.alerts.errors.push(`deliver: ${e instanceof Error ? e.message : String(e)}`);
      }
    }
  }
  return summary;
}

async function collectPrices(
  deps: CollectorDeps,
  opts: CollectOptions,
  summary: CollectSummary,
  fired: AlertEvent[],
): Promise<CollectSummary> {
  const { store } = deps;
  const startMs = deps.now().getTime();
  const budget = opts.budgetMs ?? 100_000;
  const gap = opts.gapMs ?? 400;
  const categories = opts.categories ?? EXCHANGE_CATEGORIES;

  // Leagues
  const leaguesRes = await deps.fetchJson(`${NINJA_BASE}/leagues`, null);
  if (leaguesRes.status !== 200) throw new Error(`poe.ninja leagues: HTTP ${leaguesRes.status}`);
  const all = classifyLeagues(leaguesRes.body);
  if (all.length === 0) throw new Error("poe.ninja returned no usable leagues");
  await store.upsertLeagues(all, deps.now().toISOString());
  const leagues = all.filter((l) => TIER_KINDS[opts.tier].includes(l.kind));
  summary.leagues = leagues.map((l) => l.id);

  let requests = 0;
  for (const league of leagues) {
    let context: DivineContext | null = null;

    for (const category of categories) {
      if (deps.now().getTime() - startMs > budget) {
        summary.stoppedEarly = true;
        return summary;
      }
      const state = (await store.getState(league.id, category)) ?? {
        etag: null, lastAttemptAt: null, lastSuccessAt: null, divineChaos: null, divineChange7d: null,
      };
      if (category === "Currency" && state.divineChaos) {
        context = { divinePriceChaos: state.divineChaos, divineChange7dPct: state.divineChange7d };
      }
      const nowIso = deps.now().toISOString();
      if (state.lastAttemptAt && deps.now().getTime() - Date.parse(state.lastAttemptAt) < MIN_INTERVAL_MS[opts.tier]) {
        summary.results.push({ leagueId: league.id, category, status: "skipped", note: "attempted recently" });
        continue;
      }
      if (category !== "Currency" && !context) {
        summary.results.push({ leagueId: league.id, category, status: "skipped", note: "no Divine reference yet" });
        continue;
      }

      // Claim before fetching, so overlapping triggers cannot double-request poe.ninja.
      await store.setState(league.id, category, { ...state, lastAttemptAt: nowIso });

      if (requests > 0) await deps.sleep(gap);
      if (deps.now().getTime() - startMs > budget) {
        await store.setState(league.id, category, state); // release the claim for the next run
        summary.stoppedEarly = true;
        return summary;
      }
      requests++;
      const url = `${NINJA_BASE}/exchange/current/overview?league=${encodeURIComponent(league.id)}&type=${encodeURIComponent(category)}`;
      const base = { leagueId: league.id, category, startedAt: nowIso };
      let res: FetchResult;
      try {
        res = await deps.fetchJson(url, state.etag);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        await store.setState(league.id, category, { ...state, lastAttemptAt: nowIso });
        await store.recordRun({ ...base, status: "error", divineChaos: null, itemCount: null, warnings: [], error: msg });
        summary.results.push({ leagueId: league.id, category, status: "error", note: msg });
        continue;
      }

      if (res.status === 304) {
        await store.setState(league.id, category, { ...state, lastAttemptAt: nowIso });
        await store.recordRun({ ...base, status: "not_modified", divineChaos: null, itemCount: null, warnings: [], error: null });
        summary.results.push({ leagueId: league.id, category, status: "not_modified" });
        continue;
      }
      if (res.status === 404 || (res.status === 200 && !hasLines(res.body))) {
        // Category not offered in this league (e.g. a league mechanic that ended).
        await store.setState(league.id, category, { ...state, etag: res.etag, lastAttemptAt: nowIso });
        await store.recordRun({ ...base, status: "empty", divineChaos: null, itemCount: 0, warnings: [], error: null });
        summary.results.push({ leagueId: league.id, category, status: "empty" });
        continue;
      }
      if (res.status !== 200) {
        const msg = `HTTP ${res.status}`;
        await store.setState(league.id, category, { ...state, lastAttemptAt: nowIso });
        await store.recordRun({ ...base, status: "error", divineChaos: null, itemCount: null, warnings: [], error: msg });
        summary.results.push({ leagueId: league.id, category, status: "error", note: msg });
        if (res.status === 429) {
          summary.stoppedEarly = true; // back off entirely; try again next scheduled run
          return summary;
        }
        continue;
      }

      const raw = res.body as RawExchangeOverview;
      try {
        const snap = normalizeExchangeOverview(raw, {
          league: league.id,
          category,
          fetchedAt: nowIso,
          context: category === "Currency" ? undefined : context ?? undefined,
        });
        const count = await store.ingest(league.id, category, nowIso, toIngestItems(snap.items, iconMap(raw)));
        const next: CategoryState = { ...state, etag: res.etag, lastAttemptAt: nowIso, lastSuccessAt: nowIso };
        if (category === "Currency") {
          next.divineChaos = snap.divinePriceChaos;
          next.divineChange7d = snap.divineChange7dPct;
          context = { divinePriceChaos: snap.divinePriceChaos, divineChange7dPct: snap.divineChange7dPct };
        }
        await store.setState(league.id, category, next);
        await store.recordRun({ ...base, status: "ok", divineChaos: snap.divinePriceChaos, itemCount: count, warnings: snap.warnings, error: null });
        summary.results.push({ leagueId: league.id, category, status: "ok", items: count });
        if (deps.alerts) {
          // Alert problems must never stop price collection.
          try {
            const events = await deps.alerts.evaluate(league.id, category, nowIso);
            fired.push(...events);
            summary.alerts.fired += events.length;
          } catch (e) {
            summary.alerts.errors.push(`${league.id}/${category}: ${e instanceof Error ? e.message : String(e)}`);
          }
        }
      } catch (e) {
        const rejected = e instanceof DataIntegrityError;
        const msg = e instanceof Error ? e.message : String(e);
        // Do not store the ETag of rejected data, so the next run re-checks it.
        await store.setState(league.id, category, { ...state, lastAttemptAt: nowIso });
        await store.recordRun({ ...base, status: rejected ? "rejected" : "error", divineChaos: null, itemCount: null, warnings: [], error: msg });
        summary.results.push({ leagueId: league.id, category, status: rejected ? "rejected" : "error", note: msg });
      }
    }
  }
  return summary;
}

function hasLines(body: unknown): boolean {
  return !!body && Array.isArray((body as { lines?: unknown }).lines) && (body as { lines: unknown[] }).lines.length > 0;
}


// ===== collect/index.ts =====
/**
 * Supabase Edge Function: collect
 *
 * Triggered by pg_cron (see supabase/setup/schedule.sql):
 *   POST /functions/v1/collect?tier=fast   every 15 min  (current challenge softcore)
 *   POST /functions/v1/collect?tier=slow   hourly        (challenge HC, Standard, Hardcore)
 *   POST /functions/v1/collect?mode=discord-test           (sends one test message to Discord)
 *
 * After each stored (league, category) snapshot the alert rules are evaluated in
 * the database (evaluate_alerts); everything that fired is sent to the Discord
 * webhook in app_config ('discord_webhook_url') once per run.
 *
 * Auth: deployed with verify_jwt = false and protected by a token kept in the
 * private table app_config (key 'collector_token'); the cron job sends it in
 * the x-collector-token header. The per-category minimum interval in the
 * collector is a second line of defence against repeated calls.
 */



const VERSION = "0.3.0";

Deno.serve(async (req) => {
  const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, {
    auth: { persistSession: false },
  });

  const config = await loadConfig(supabase);
  const token = req.headers.get("x-collector-token");
  if (!config.collector_token || token !== config.collector_token) {
    return new Response("Forbidden", { status: 403 });
  }

  const params = new URL(req.url).searchParams;
  const tier: Tier = params.get("tier") === "slow" ? "slow" : "fast";
  const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

  const postJson: PostJson = async (url, body) => {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(10_000),
    });
    await res.body?.cancel();
    const retry = Number(res.headers.get("retry-after"));
    return { status: res.status, retryAfterMs: Number.isFinite(retry) && retry > 0 ? retry * 1000 : null };
  };

  if (params.get("mode") === "discord-test") {
    const hook = config.discord_webhook_url;
    if (!hook) return Response.json({ ok: false, error: "No Discord webhook saved yet" }, { status: 400 });
    const error = await sendDiscord(postJson, sleep, hook, testPayload(new Date().toISOString()));
    return Response.json({ ok: !error, error }, { status: error ? 502 : 200 });
  }

  const alerts: AlertHooks = {
    async evaluate(leagueId, category, at) {
      const { data, error } = await supabase.rpc("evaluate_alerts", {
        p_league_id: leagueId,
        p_category: category,
        p_now: at,
      });
      if (error) throw error;
      return (data ?? []) as AlertEvent[];
    },
    async deliver(events) {
      const hook = config.discord_webhook_url;
      for (const { payload, ids } of buildPayloads(events)) {
        const error = hook ? await sendDiscord(postJson, sleep, hook, payload) : "No Discord webhook saved yet";
        await supabase.rpc("mark_alert_delivery", { p_ids: ids, p_error: error });
      }
    },
  };
  const userAgent = `poe-economy-tools/${VERSION} (contact: ${config.ninja_contact ?? "not set"})`;

  const fetchJson = async (url: string, etag: string | null) => {
    const headers: Record<string, string> = { "User-Agent": userAgent, Accept: "application/json" };
    if (etag) headers["If-None-Match"] = etag;
    const res = await fetch(url, { headers, signal: AbortSignal.timeout(20_000) });
    const body = res.status === 200 ? await res.json() : (await res.body?.cancel(), null);
    return { status: res.status, etag: res.headers.get("etag"), body };
  };

  const store: Store = {
    async upsertLeagues(leagues, seenAt) {
      const { error } = await supabase.from("leagues").upsert(
        leagues.map((l) => ({ id: l.id, name: l.name, kind: l.kind, last_seen_at: seenAt, is_active: true })),
        { onConflict: "id" },
      );
      if (error) throw error;
      const ids = leagues.map((l) => `"${l.id.replaceAll('"', '\\"')}"`).join(",");
      const { error: e2 } = await supabase.from("leagues").update({ is_active: false }).not("id", "in", `(${ids})`);
      if (e2) throw e2;
    },
    async getState(leagueId, category) {
      const { data, error } = await supabase
        .from("collection_state")
        .select("etag,last_attempt_at,last_success_at,divine_chaos,divine_change7d")
        .eq("league_id", leagueId)
        .eq("category", category)
        .maybeSingle();
      if (error) throw error;
      if (!data) return null;
      return {
        etag: data.etag,
        lastAttemptAt: data.last_attempt_at,
        lastSuccessAt: data.last_success_at,
        divineChaos: data.divine_chaos,
        divineChange7d: data.divine_change7d,
      } satisfies CategoryState;
    },
    async setState(leagueId, category, s) {
      const { error } = await supabase.from("collection_state").upsert(
        {
          league_id: leagueId,
          category,
          etag: s.etag,
          last_attempt_at: s.lastAttemptAt,
          last_success_at: s.lastSuccessAt,
          divine_chaos: s.divineChaos,
          divine_change7d: s.divineChange7d,
        },
        { onConflict: "league_id,category" },
      );
      if (error) throw error;
    },
    async ingest(leagueId, category, capturedAt, items) {
      const { data, error } = await supabase.rpc("ingest_snapshot", {
        p_league_id: leagueId,
        p_category: category,
        p_captured_at: capturedAt,
        p_items: items,
      });
      if (error) throw error;
      return data as number;
    },
    async recordRun(r) {
      const { error } = await supabase.from("collection_runs").insert({
        league_id: r.leagueId,
        category: r.category,
        started_at: r.startedAt,
        status: r.status,
        divine_chaos: r.divineChaos,
        item_count: r.itemCount,
        warnings: r.warnings.length ? r.warnings : null,
        error: r.error,
      });
      if (error) throw error;
    },
  };

  try {
    const summary = await collect(
      { fetchJson, store, now: () => new Date(), sleep, alerts },
      { tier, budgetMs: 100_000 },
    );
    return Response.json(summary);
  } catch (e) {
    console.error(e);
    return Response.json({ error: e instanceof Error ? e.message : String(e) }, { status: 500 });
  }
});

async function loadConfig(supabase: ReturnType<typeof createClient>) {
  const { data } = await supabase.from("app_config").select("key,value").in("key", ["collector_token", "ninja_contact", "discord_webhook_url"]);
  const out: Record<string, string> = {};
  for (const row of data ?? []) out[row.key as string] = row.value as string;
  return out as { collector_token?: string; ninja_contact?: string; discord_webhook_url?: string };
}
